\begin{proof}
  This is the final conclusion packaged into Theorem~\ref{thm:main}.
\end{proof}

n35013.content:
\begin{definition}\label{def:H_n}
  \lean{HypergraphLowerBound.H}
  \leanok%
  Write $H(n)$ for the largest $k\in\mathbb{N}$ such that there exists a finite edge family $\mathcal{H}$ with $|\bigcup \mathcal{H}|=k$ and no partition of size greater than $n$.
  Equivalently, this is the paper's definition with the ``no isolated vertices'' condition built into the edge-set encoding.
\end{definition}

n35014.content:
\begin{definition}\label{def:k_n}
  \lean{HypergraphLowerBound.k}
  \leanok%
  Define the sequence $k:\mathbb{N}\to\mathbb{N}$ by $k(0)=0$, $k(1)=1$, and
  \[
    k(n)=\lfloor n/2\rfloor+k(\lfloor n/2\rfloor)+k(\lfloor(n+1)/2\rfloor)
    \quad(n\ge 2).
  \]
\end{definition}

n35015.content:
\begin{definition}\label{def:u_G}
  \lean{HypergraphLowerBound.uniqueCoverage}
  \leanok%
  For a hypergraph $G=(V,\mathcal{H})$ and a chosen edge family $\mathcal{P}\subseteq \mathcal{H}$, define
  \[
    u_G(\mathcal{P}):=|\{v\in V:\text{$v$ belongs to exactly one edge of }\mathcal{P}\}|.
  \]
\end{definition}

n35016.content:
\begin{lemma}\label{lem:partition_u}
  \lean{HypergraphLowerBound.partition_iff_uniqueCoverage}
  \leanok%
  \uses{def:u_G}
  A hypergraph $G$ contains no partition of size greater than $n$ if and only if
  \[
    u_G(\mathcal{P})\le n
    \qquad\text{for every }\mathcal{P}\subseteq \mathcal{H}.
  \]
\end{lemma}

n35017.content:
\begin{proof}
  If $(D,\mathcal{P})$ is a partition of size $m$, then every vertex of $D$ is counted by $u_G(\mathcal{P})$, so $u_G(\mathcal{P})\ge m$.
  Conversely, if $u_G(\mathcal{P})>n$, let $D$ be the set of vertices counted by $u_G(\mathcal{P})$; then $(D,\mathcal{P})$ is a partition of size $u_G(\mathcal{P})$.
\end{proof}

n35018.content:
\begin{definition}\label{def:support_pattern}
  \lean{HypergraphLowerBound.SupportPattern}
  \leanok%
  Fix $t\ge 2$.
  A \emph{support pattern} on $[t]:=\{1,\dots,t\}$ is a subset of $[t]$ of size at least $2$.
\end{definition}

n35020.content:
\begin{definition}\label{def:n_frame}
  \lean{HypergraphLowerBound.IsFrame}
  \leanok%
  \uses{def:omega}
  Let $\mathbf{n}=(n_1,\dots,n_t)\in\mathbb{N}^t$.
  We say that $\mathcal{F}$ is an \emph{$\mathbf{n}$-frame} if
  \[
    \omega_{\mathcal{F}}(T,I)\le \sum_{j\in T\setminus I} n_j
    \qquad\text{for every }I\subseteq T\subseteq [t].
  \]
\end{definition}

n35021.content:
\begin{definition}\label{def:substitution}
  \lean{HypergraphLowerBound.substitutionHypergraph}
  \leanok%
  \uses{def:support_pattern}
  Let $\mathcal{F}$ be a support multiset on $[t]$.
  Let $G_i=(V_i,\mathcal{H}_i)$, $1\le i\le t$, be hypergraphs with pairwise disjoint vertex sets and pairwise disjoint edge sets.
  The \emph{substitution hypergraph}
  \[
    \mathcal{F}[G_1,\dots,G_t]
  \]
  has edge set $\mathcal{H}_1\sqcup\cdots\sqcup\mathcal{H}_t$, and its vertex set consists of $V_1\sqcup\cdots\sqcup V_t$ together with one new vertex $x_S$ for each occurrence of a support pattern $S\in \mathcal{F}$.
  The new vertex $x_S$ is incident to every edge of $\mathcal{H}_i$ for every $i\in S$.
  In the formalization this is realized by tagging the block vertices and the support-vertex occurrences, so the disjointness is built into the construction itself.
  The surrounding indexed block family is packaged by the alias \texttt{HypergraphLowerBound.BlockFamily}, and support occurrences are indexed by \texttt{HypergraphLowerBound.SupportOcc}.
\end{definition}

n35024.content:
\begin{corollary}\label{cor:frame_recurrence}
  \lean{HypergraphLowerBound.frame_recurrence}
  \leanok%
  \uses{thm:substitution, def:n_frame}
  Suppose that for $1\le i\le t$ there is a hypergraph $G_i$ with exactly $n_i$ edges, no partition of size greater than $n_i$, and $a_i$ vertices.
  If $\mathcal{F}$ is an $(n_1,\dots,n_t)$-frame, then $\mathcal{F}[G_1,\dots,G_t]$ has exactly $n_1+\cdots+n_t$ edges, no partition of size greater than $n_1+\cdots+n_t$, and
  \[
    a_1+\cdots+a_t+|\mathcal{F}|
  \]
  vertices.
  In the edge-set formalization this is the version of the paper's statement in which the ``no isolated vertices'' condition is implicit.
  The corresponding formal statement packages these count assumptions into the structure \texttt{HypergraphLowerBound.CountedBlocks}.
\end{corollary}

n35025.content:
\begin{proof}
  \uses{thm:substitution}
  The edge set is the disjoint union of the edge sets of the blocks, so the edge count is additive.
  Every old vertex remains non-isolated, and every new support vertex meets every edge in at least one block from its support.
  The vertex count is immediate, and the partition bound is Theorem~\ref{thm:substitution}.
\end{proof}

n35026.content:
\begin{proposition}\label{prop:finite_bank}
  \lean{HypergraphLowerBound.finite_bank_valid}
  \leanok%
  \uses{def:n_frame}
  Every exact small frame listed in the paper, every booster, and every residue gadget $R_r$ is a valid frame for its stated capacity vector.
\end{proposition}

n35029.content:
\begin{theorem}\label{thm:constructive_An}
  \lean{HypergraphLowerBound.constructive_An}
  \leanok%
  \uses{def:A_n, cor:frame_recurrence, prop:finite_bank}
  For every $n\ge 1$ there exists a hypergraph $G$ with exactly $n$ distinct edges, no partition of size greater than $n$, and $|V(G)|=A_n$.
  In the formalization, the data of such a witness are packaged in the structure \texttt{HypergraphLowerBound.Witness}, and then unwrapped into the existential statement recorded here.
  The corresponding development also exposes the intermediate public witness theorems \texttt{HypergraphLowerBound.A_witness} and \texttt{HypergraphLowerBound.thm_main_pointwise}.
  By choosing one such witness for each $n$, one obtains an explicit recursive family; as above, the paper's ``no isolated vertices'' clause is implicit in the edge-set encoding.
\end{theorem}

n35030.content:
\begin{proof}
  \uses{cor:frame_recurrence, prop:finite_bank, def:A_n}
  We argue by induction on $n$.
  For $n=1$, take a single edge containing a single vertex.
  For $2\le n<60$, each row of the finite bootstrap table specifies one of four possibilities
  (binary, exact-frame, booster, balanced four-way), and Corollary~\ref{cor:frame_recurrence}
  applied to the smaller witnesses yields the stated vertex count.
  For $n\ge 60$, the balanced four-way split with $\lfloor n/12\rfloor$ copies of the $13$-vertex
  four-way core and one residue gadget gives $A_n$ vertices by the same corollary.
\end{proof}

n35031.content:
\begin{lemma}\label{lem:k_four_way}
  \lean{HypergraphLowerBound.k_four_way}
  \leanok%
  \uses{def:k_n}
  For every $m\ge 1$,
  \begin{align*}
    k_{4m}   & =4k_m+4m,            \\
    k_{4m+1} & =3k_m+k_{m+1}+4m,    \\
    k_{4m+2} & =2k_m+2k_{m+1}+4m+1, \\
    k_{4m+3} & =k_m+3k_{m+1}+4m+2.
  \end{align*}
\end{lemma}

n35032.content:
\begin{proof}
  \uses{def:k_n}
  The defining recurrence for $k_n$ immediately gives
  $k_{2m}=m+2k_m$ and $k_{2m+1}=m+k_m+k_{m+1}$.
  Applying these identities once more gives the displayed four-way formulas.
\end{proof}

n35033.content:
\begin{lemma}\label{lem:floor_26_25}
  \lean{HypergraphLowerBound.floor_26_25}
  \leanok%
  \uses{def:A_n}
  For every integer $m\ge 15$,
  \begin{align*}
    e_0(m) & \ge \frac{26}{25}\cdot 4m, \\
    e_1(m) & \ge \frac{26}{25}\cdot 4m, \\
    e_2(m) & \ge \frac{26}{25}(4m+1),   \\
    e_3(m) & \ge \frac{26}{25}(4m+2).
  \end{align*}
\end{lemma}

n35034.content:
\begin{proof}
  Using $\lfloor x\rfloor\ge x-1$ and direct calculation, each difference is at least $(13m-75)/75$, $(13m-50)/75$, $(13m-28)/75$, $(13m-52)/75$ respectively, all nonneg for $m\ge 15$.
\end{proof}

n35035.content:
\begin{proposition}\label{prop:bootstrap_26_25}
  \lean{HypergraphLowerBound.bootstrap_26_25}
  \leanok%
  \uses{def:A_n, def:k_n}
  For every integer $n$ with $15\le n<60$,
  \[
    25A_n\ge 26k_n,
  \]
  and equality holds if and only if $n=17$.
  Equivalently, with $\Delta_n:=25A_n-26k_n$, one has $\Delta_n\ge 0$ for every $15\le n<60$, with equality only at $n=17$.
\end{proposition}

n35036.content:
\begin{proof}
  This is the finite table check.
\end{proof}

n35037.content:
\begin{theorem}\label{thm:uniform_26_25}
  \lean{HypergraphLowerBound.uniform_26_25}
  \leanok%
  \uses{prop:bootstrap_26_25, lem:floor_26_25, lem:k_four_way, def:A_n, def:k_n}
  For every integer $n\ge 15$,
  \[
    A_n\ge \frac{26}{25}\,k_n.
  \]
  Together with Theorem~\ref{thm:constructive_An}, this yields the sequence-level statement Theorem~\ref{thm:main}; Corollary~\ref{cor:main_H_lower_bound} is its extracted $H(n)$ consequence.
\end{theorem}

n35038.content:
\begin{proof}
  \uses{prop:bootstrap_26_25, lem:floor_26_25, lem:k_four_way}
  The range $15\le n<60$ is Proposition~\ref{prop:bootstrap_26_25}.
  For $n\ge 60$, write $n=4m+r$ with $0\le r\le 3$ and note $m\ge 15$.
  Each case follows from Definition~\ref{def:A_n}, Lemma~\ref{lem:floor_26_25}, Lemma~\ref{lem:k_four_way}, and the inductive hypothesis.
\end{proof}

n35040.content:
\begin{definition}\label{def:lubell_frame}
  \lean{HypergraphLowerBound.lubellFrame}
  \leanok%
  \uses{def:M_t}
  Let $\mathcal{L}_t$ be the support multiset on $[t]$ that contains every $j$-subset of $[t]$ with multiplicity
  \[
    \frac{M_t}{\binom{t-1}{j-1}}
    \qquad(2\le j\le t).
  \]
\end{definition}

n35041.content:
\begin{proposition}\label{prop:lubell}
  \lean{HypergraphLowerBound.lubell_is_frame}
  \leanok%
  \uses{def:lubell_frame, def:n_frame, def:M_t}
  For every $t\ge 2$, the support multiset $\mathcal{L}_t$ is an $(M_t,\dots,M_t)$-frame.
  Moreover,
  \[
    |\mathcal{L}_t|=M_t\,t\,(h_t-1),
    \qquad
    h_t:=1+\frac12+\cdots+\frac1t.
  \]
\end{proposition}

n35042.content:
\begin{proof}
  \uses{def:lubell_frame, def:n_frame, def:M_t}
  Fix $I\subseteq T\subseteq [t]$ with $i:=|I|$ and $z:=|T\setminus I|$.
  A support pattern of size $r+1$ contributes when it chooses one element of $I$ and $r$ elements of $T\setminus I$.
  Using the beta-integral identity
  $1/\binom{t-1}{r} = t\int_0^1 x^r{(1-x)}^{t-1-r}\,dx$,
  one computes
  $\omega_{\mathcal{L}_t}(T,I)=iM_t\cdot z/(t-z)$.
  Since $i\le t-z$, this is at most $zM_t$.
  The size formula follows from
  $|\mathcal{L}_t|=\sum_{j=2}^{t}\binom{t}{j}\frac{M_t}{\binom{t-1}{j-1}}
    =M_t\sum_{j=2}^{t}\frac{t}{j}
    =M_t\,t\,(h_t-1)$.
\end{proof}

n35043.content:
\begin{proposition}\label{prop:digit_sum}
  \lean{HypergraphLowerBound.digit_sum_formula}
  \leanok%
  \uses{def:k_n}
  Let $s_2(m)$ denote the sum of the binary digits of $m$.
  Then for every $n\ge 1$,
  \[
    k_n=n+\sum_{j=0}^{n-1}s_2(j).
  \]
\end{proposition}

n35044.content:
\begin{proof}
  \uses{def:k_n}
  Set $k_0:=0$ and $\Delta_n:=k_n-k_{n-1}$ for $n\ge 1$.
  From the recurrence, $\Delta_{2m}=1+\Delta_m$ and $\Delta_{2m+1}=\Delta_{m+1}$.
  Define $a_n:=1+s_2(n-1)$; the same binary-digit argument gives $a_{2m}=1+a_m$ and $a_{2m+1}=a_{m+1}$, with $a_1=1=\Delta_1$.
  Therefore $\Delta_n=a_n$ for all $n$, and summing yields $k_n=n+\sum_{j=0}^{n-1}s_2(j)$.
\end{proof}

n35045.content:
\begin{theorem}\label{thm:fixed_t}
  \lean{HypergraphLowerBound.fixed_t_bound}
  \leanok%
  \uses{prop:lubell, cor:frame_recurrence, def:H_n}
  Fix $t\ge 2$.
  There exists a constant $C_t>0$ such that
  \[
    H(n)\ge \frac{h_t-1}{\log_2 t}\,n\log_2 n - C_t n
    \qquad\text{for all }n\ge 1.
  \]
\end{theorem}

n35048.content:
\begin{proof}
  \uses{thm:fixed_t, prop:digit_sum}
  By Proposition~\ref{prop:digit_sum}, one obtains the upper bound $k_n\le \frac12 n\log_2 n + O(n)$ used in the formal proof.
  Fix $\varepsilon>0$ and choose $t$ so large that $2(h_t-1)/\log_2 t>2\ln 2 - \varepsilon$.
  Then Theorem~\ref{thm:fixed_t} gives $H(n)\ge ((h_t-1)/\log_2 t)n\log_2 n - O_t(n)$.
  Dividing by the explicit upper bound for $k_n$ and letting $n\to\infty$ yields the result since $\varepsilon$ was arbitrary.
\end{proof}
